/*
 * [演算法說明]
 * 這是一個子集和 (Subset Sum) 問題，是 0/1 背包問題的一個變種。
 * 給定一組行李重量，判斷是否能將其分成兩組，使得兩組的重量相等。
 * 
 * 演算法步驟：
 * 1. 計算所有行李的總重量 sum。
 * 2. 如果 sum 是奇數，則不可能平分，輸出 "NO"。
 * 3. 如果 sum 是偶數，目標是判斷是否能選出一個子集，其重量之和等於 sum / 2。
 * 4. 使用動態規劃：dp[i] 表示是否能達到重量 i。
 *    dp[i] = dp[i] | dp[i - weight]
 */

#include <iostream>
#include <vector>
#include <numeric>
#include <sstream>
#include <string>

using namespace std;

bool can_partition() {
    string line;
    if (!getline(cin, line) || line.empty()) return false;

    stringstream ss(line);
    vector<int> weights;
    int w;
    while (ss >> w) weights.push_back(w);

    int total_sum = accumulate(weights.begin(), weights.end(), 0);
    if (total_sum % 2 != 0) return false;

    int target = total_sum / 2;
    vector<bool> dp(target + 1, false);
    dp[0] = true;

    for (int weight : weights) {
        for (int j = target; j >= weight; --j) {
            if (dp[j - weight]) dp[j] = true;
        }
    }

    return dp[target];
}

int main() {
    int m;
    string line;
    if (getline(cin, line)) {
        m = stoi(line);
        while (m--) {
            if (can_partition()) cout << "YES" << endl;
            else cout << "NO" << endl;
        }
    }
    return 0;
}
